@@ -0,0 +1,24 @@
+// Sites: each location belongs to one site, and a batch is in the site of its
+// location. Items, suppliers, recipes and dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site used when a request does not name one. */
+export const DEFAULT_SITE = "main";
+
+/** The site `id`, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when a location id belongs to `site` (always true when `site` is undefined). */
+export function locationInSite(store, locationId, site) {
+  if (site === undefined) return true;
+  return store.data.locations.some((l) => l.id === locationId && l.site === site);
+}
+
+/** True when a batch is in `site` (always true when `site` is undefined). */
+export function batchInSite(store, batch, site) {
+  return locationInSite(store, batch.location, site);
+}
